// Unit tests for util.js. Run with `node --test templates/util_test.js`.
//
// The slugifyName parity cases are generated by the Go test
// TestDashboardUtilSlugParity from config.SlugifyName and handed over via the
// GOPROX_SLUG_CASES env var, so the Go and JS implementations cannot silently
// drift apart.
"use strict";

const test = require("node:test");
const assert = require("node:assert");
const fs = require("node:fs");

const util = require("./util.js");

function slugParityCases() {
  const file = process.env.GOPROX_SLUG_CASES;
  if (!file) return [];
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

test("slugifyName matches config.SlugifyName", () => {
  const cases = slugParityCases();
  assert.ok(cases.length > 0, "no parity cases were provided");
  for (const c of cases) {
    assert.strictEqual(
      util.slugifyName(c.name),
      c.slug,
      "slug mismatch for " + JSON.stringify(c.name)
    );
  }
});

test("slugifyName basics", () => {
  assert.strictEqual(util.slugifyName("My App"), "my-app");
  assert.strictEqual(util.slugifyName("  R Studio!  "), "r-studio");
  assert.strictEqual(util.slugifyName("a__b--c"), "a__b-c");
  assert.strictEqual(util.slugifyName(""), "service");
  assert.strictEqual(util.slugifyName(null), "service");
});

test("nextServiceID uniquifies like AddService", () => {
  assert.strictEqual(util.nextServiceID("app", []), "app");
  assert.strictEqual(util.nextServiceID("app", ["other"]), "app");
  assert.strictEqual(util.nextServiceID("app", ["app"]), "app-2");
  assert.strictEqual(util.nextServiceID("app", ["app", "app-2"]), "app-3");
  assert.strictEqual(util.nextServiceID("app", ["app", "app-2", "app-3"]), "app-4");
});

test("autoPathFor dedups ID and path independently", () => {
  // Free ID and path.
  assert.strictEqual(util.autoPathFor("app", [], []), "/app");
  // ID collision pushes the ID (and therefore the path) to -2.
  assert.strictEqual(util.autoPathFor("app", ["app"], []), "/app-2");
  // An existing custom path owns "/myapp": the auto path must step aside
  // even though the ID "myapp" itself is free (the old server bug).
  assert.strictEqual(util.autoPathFor("myapp", [], ["/myapp"]), "/myapp-2");
  assert.strictEqual(
    util.autoPathFor("myapp", [], ["/myapp", "/myapp-2"]),
    "/myapp-3"
  );
});

test("mbToBytes converts MB/s to bytes/s", () => {
  assert.strictEqual(util.mbToBytes(""), 0);
  assert.strictEqual(util.mbToBytes("10"), 10485760);
  assert.strictEqual(util.mbToBytes("0.5"), 524288);
  assert.strictEqual(util.mbToBytes("0"), 0);
  assert.strictEqual(util.mbToBytes("-1"), -1);
  assert.strictEqual(util.mbToBytes("abc"), -1);
});

test("bytesToMB renders empty for unlimited", () => {
  assert.strictEqual(util.bytesToMB(0), "");
  assert.strictEqual(util.bytesToMB(10485760), "10");
  assert.strictEqual(util.bytesToMB(524288), "0.5");
});

test("esc escapes HTML attribute and text contexts", () => {
  assert.strictEqual(
    util.esc('<a href="x">&'),
    "&lt;a href=&quot;x&quot;&gt;&amp;"
  );
});
